<div class="page-actions"><div><h2>Reporte de inventario</h2><p><?= number_format(count($rows)) ?> activos registrados en SIGATI.</p></div><div class="actions"><a class="btn btn-light" href="javascript:window.print()">Imprimir</a><a class="btn btn-primary" href="<?= url('reports/inventory/csv') ?>">Descargar CSV</a></div></div>
<section class="panel report-summary"><div><span>Total</span><strong><?= count($rows) ?></strong></div><div><span>Con responsable</span><strong><?= count(array_filter($rows,fn($r)=>!empty($r['responsable']))) ?></strong></div><div><span>Sin serie</span><strong><?= count(array_filter($rows,fn($r)=>empty($r['serie']))) ?></strong></div><div><span>Sin área</span><strong><?= count(array_filter($rows,fn($r)=>empty($r['area']))) ?></strong></div></section>
<section class="panel table-panel"><div class="table-responsive"><table class="data-table dense"><thead><tr><?php if($rows):foreach(array_keys($rows[0]) as $h):?><th><?= e(ucwords(str_replace('_',' ',$h))) ?></th><?php endforeach;endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $k=>$v):?><td><?= e($v??'—') ?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section>
